const baseUrl = process.env.SANDBOX_BASE_URL ?? "https://sandbox.tangle.tools";
const apiKey = process.env.TANGLE_API_KEY;
if (!apiKey) throw new Error("Set TANGLE_API_KEY in a trusted runtime");
// Run with Node.js 22+ and the project’s TypeScript runner.
const url = new URL(`/auth/account`, baseUrl);
const headers: Record<string, string> = { Authorization: `Bearer ${apiKey}`, Accept: "*/*" };
const response = await fetch(url, { method: "DELETE", headers });
if (!response.ok) throw new Error(`HTTP ${response.status}: ${await response.text()}`);
const reader = response.body?.getReader();
if (reader) {
  const decoder = new TextDecoder();
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    process.stdout.write(decoder.decode(value, { stream: true }));
  }
  process.stdout.write(decoder.decode());
} else {
  process.stdout.write(await response.text());
}

