import os
import sys
from urllib.error import HTTPError
from urllib.parse import quote, urlencode
from urllib.request import Request, urlopen

api_key = os.environ.get("TANGLE_API_KEY")
if not api_key: raise SystemExit("Set TANGLE_API_KEY in a trusted runtime")
base_url = os.environ.get("SANDBOX_BASE_URL", "https://sandbox.tangle.tools").rstrip("/")
url = f"{base_url}/auth/cli/login"
query = {}
_callback_url = os.environ.get("SANDBOX_CALLBACK_URL")
if not _callback_url: raise SystemExit("Set SANDBOX_CALLBACK_URL")
if _callback_url is not None: query["callback_url"] = _callback_url
if query: url += "?" + urlencode(query, doseq=True)
headers = {"Authorization": f"Bearer {api_key}", "Accept": "*/*"}
request = Request(url, data=None, headers=headers, method="GET")
try:
    with urlopen(request, timeout=float(os.environ.get("SANDBOX_TIMEOUT_SECONDS", "300"))) as response:
        while chunk := response.read(8192):
            sys.stdout.buffer.write(chunk)
except HTTPError as error:
    detail = error.read().decode("utf-8", errors="replace")
    raise SystemExit(f"HTTP {error.code}: {detail}") from error

const baseUrl = process.env.SANDBOX_BASE_URL ?? "https://sandbox.tangle.tools";
const apiKey = process.env.TANGLE_API_KEY;
if (!apiKey) throw new Error("Set TANGLE_API_KEY in a trusted runtime");
// Run with Node.js 22+ and the project’s TypeScript runner.
const url = new URL(`/auth/login`, baseUrl);
const provider = process.env.SANDBOX_PROVIDER;
if (provider !== undefined) url.searchParams.set("provider", provider);
const mode = process.env.SANDBOX_MODE;
if (mode !== undefined) url.searchParams.set("mode", mode);
