if (!id) throw new Error("Set SANDBOX_ID");
const leaseId = process.env.SANDBOX_LEASE_ID;
if (!leaseId) throw new Error("Set SANDBOX_LEASE_ID");
const path = process.env.SANDBOX_PATH;
