const apiKey = process.env.TANGLE_API_KEY;
// Run with Node.js 22+ and the project’s TypeScript runner.
if (!apiKey) throw new Error("Set TANGLE_API_KEY in a trusted runtime");
const id = process.env.SANDBOX_ID;
if (!id) throw new Error("Set SANDBOX_ID");
const url = new URL(`/v1/startup-scripts/${encodeURIComponent(id)}`, baseUrl);
const headers: Record<string, string> = { Authorization: `Bearer ${apiKey}`, Accept: "*/*" };
// Save a request body that matches the schema above as request.json.
const body = await readFile(process.env.SANDBOX_REQUEST_FILE ?? "request.json", "utf8");
headers["Content-Type"] = "application/json";
const response = await fetch(url, { method: "PUT", headers, body });
if (!response.ok) throw new Error(`HTTP ${response.status}: ${await response.text()}`);
const reader = response.body?.getReader();
if (reader) {
  const decoder = new TextDecoder();
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    process.stdout.write(decoder.decode(value, { stream: true }));
  }
  process.stdout.write(decoder.decode());
} else {
  process.stdout.write(await response.text());
}

